CREATE TABLE IF NOT EXISTS gis_final_identity_crosswalk (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_feature_id uuid NOT NULL REFERENCES gis_spatial_features(id) ON DELETE CASCADE, target_feature_id uuid REFERENCES gis_spatial_features(id) ON DELETE SET NULL, canonical_state_code text, source_lga_code text, target_lga_code text, score numeric(6,5) NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'REVIEW', evidence jsonb NOT NULL DEFAULT '{}'::jsonb, crosswalk_version text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_feature_id));
CREATE INDEX IF NOT EXISTS idx_gis_final_crosswalk_status ON gis_final_identity_crosswalk(status,crosswalk_version);